@Override // ru.jecklandin.stickman.units.handlers.AbstractHandler
public void updateBoundingBox(float sceneMultiplier) {
    if (this.mControlled == null) {
        this.mBoundingBox = emptyBB();
        return;
    }
    UPoint[] boundingBox = this.mControlled.getBoundingBox();
    float f = (80.0f / sceneMultiplier) / 1.5f;
    this.mCenter.x = boundingBox[1].x + f;
    this.mCenter.y = boundingBox[0].y - f;
    this.mBoundingBox = calculateBoundingBox(this.mCenter, sceneMultiplier);
}
